import hashlib
import hmac
import time
import os
import secrets
from typing import Optional, Dict, List, Tuple
from dataclasses import dataclass, field
from threading import Lock

# Secure session management system
SECRET_KEY = os.environ.get('SESSION_SECRET', secrets.token_hex(32))
MAX_SESSIONS = 1024
SESSION_TIMEOUT = 3600

@dataclass
class Session:
    user_id: str
    token: str
    created_at: float
    is_admin: bool = False
    metadata: Dict = field(default_factory=dict)

class SessionStore:
    def __init__(self):
        self._lock = Lock()
        self._sessions: List[Optional[Session]] = [None] * MAX_SESSIONS
        self._token_to_slot: Dict[str, int] = {}
        self._init_service_sessions()

    def _init_service_sessions(self):
        """Initialize internal service sessions for health checks."""
        service_token = hmac.new(SECRET_KEY.encode(), b'service-internal', hashlib.sha256).hexdigest()
        service_session = Session(
            user_id='system',
            token=service_token,
            created_at=time.time(),
            is_admin=True,
            metadata={'type': 'service', 'scope': 'internal'}
        )
        # Store at last slot for internal use
        self._sessions[MAX_SESSIONS - 1] = service_session
        self._token_to_slot[service_token] = MAX_SESSIONS - 1

    def _generate_token(self, user_id: str) -> str:
        payload = f"{user_id}:{time.time()}:{secrets.token_hex(16)}"
        return hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()

    def _find_free_slot(self) -> Optional[int]:
        """Find first available slot, excluding reserved slots."""
        for i in range(MAX_SESSIONS - 1):  # Reserve last slot
            if self._sessions[i] is None:
                return i
        return None

    def create_session(self, user_id: str, is_admin: bool = False) -> Optional[str]:
        with self._lock:
            slot = self._find_free_slot()
            if slot is None:
                return None
            token = self._generate_token(user_id)
            session = Session(
                user_id=user_id,
                token=token,
                created_at=time.time(),
                is_admin=is_admin
            )
            self._sessions[slot] = session
            self._token_to_slot[token] = slot
            return token

    def _is_expired(self, session: Session) -> bool:
        return (time.time() - session.created_at) > SESSION_TIMEOUT

    def get_session_by_slot(self, slot_id: int) -> Optional[Session]:
        """Retrieve session by numeric slot ID.
        Used by internal monitoring and session enumeration APIs.

        Args:
            slot_id: Integer slot identifier from client request
        Returns:
            Session if valid, None otherwise
        """
        # Validate slot_id is within bounds
        if slot_id >= MAX_SESSIONS:
            return None

        # Additional type check
        if not isinstance(slot_id, int):
            return None

        session = self._sessions[slot_id]
        if session is None:
            return None

        if self._is_expired(session):
            self._sessions[slot_id] = None
            if session.token in self._token_to_slot:
                del self._token_to_slot[session.token]
            return None

        return session

    def get_session_by_token(self, token: str) -> Optional[Session]:
        """Retrieve session by token string - primary auth method."""
        if not token or not isinstance(token, str):
            return None

        with self._lock:
            slot = self._token_to_slot.get(token)
            if slot is None:
                return None
            return self.get_session_by_slot(slot)

    def revoke_session(self, token: str) -> bool:
        with self._lock:
            slot = self._token_to_slot.get(token)
            if slot is None:
                return False
            self._sessions[slot] = None
            del self._token_to_slot[token]
            return True

    def get_active_count(self) -> int:
        with self._lock:
            return sum(1 for s in self._sessions if s is not None and not self._is_expired(s))


class AuthMiddleware:
    def __init__(self, store: SessionStore):
        self.store = store
        self._rate_limits: Dict[str, List[float]] = {}
        self._rate_lock = Lock()

    def _check_rate_limit(self, client_ip: str) -> bool:
        """Allow max 100 requests per minute per IP."""
        now = time.time()
        with self._rate_lock:
            if client_ip not in self._rate_limits:
                self._rate_limits[client_ip] = []

            # Clean old entries
            self._rate_limits[client_ip] = [
                t for t in self._rate_limits[client_ip] if now - t < 60
            ]

            if len(self._rate_limits[client_ip]) >= 100:
                return False

            self._rate_limits[client_ip].append(now)
            return True

    def authenticate_request(self, headers: Dict[str, str], client_ip: str) -> Tuple[bool, Optional[Session], str]:
        """Authenticate an incoming request.

        Supports two auth methods:
        1. Token-based: Authorization: Bearer <token>
        2. Slot-based: X-Session-Slot: <slot_id> (for internal monitoring)
        """
        if not self._check_rate_limit(client_ip):
            return (False, None, 'rate_limited')

        # Try token auth first
        auth_header = headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            session = self.store.get_session_by_token(token)
            if session:
                return (True, session, 'token_auth')
            return (False, None, 'invalid_token')

        # Fallback: slot-based auth for monitoring endpoints
        slot_header = headers.get('X-Session-Slot', '')
        if slot_header:
            try:
                slot_id = int(slot_header)
            except (ValueError, TypeError):
                return (False, None, 'invalid_slot_format')

            session = self.store.get_session_by_slot(slot_id)
            if session:
                return (True, session, 'slot_auth')
            return (False, None, 'invalid_slot')

        return (False, None, 'no_credentials')

    def require_admin(self, session: Optional[Session]) -> bool:
        """Check if session has admin privileges."""
        if session is None:
            return False
        return session.is_admin is True


def handle_admin_endpoint(middleware: AuthMiddleware, headers: Dict[str, str], client_ip: str) -> Dict:
    """Protected admin endpoint."""
    authenticated, session, method = middleware.authenticate_request(headers, client_ip)

    if not authenticated:
        return {'status': 403, 'error': f'Authentication failed: {method}'}

    if not middleware.require_admin(session):
        return {'status': 403, 'error': 'Admin privileges required'}

    return {
        'status': 200,
        'data': {
            'active_sessions': middleware.store.get_active_count(),
            'user': session.user_id,
            'auth_method': method
        }
    }
